import type { SpellCategoryId } from "./spell-categories";
import type { SpellWord, SpellRuleCategory } from "./spell-data";

type RawWordTuple = [
  word: string,
  syllablesDot: string,
  meaningBn: string,
  categories: SpellCategoryId[],
  commonMistake: string,
  mnemonicBn: string,
  difficulty?: "easy" | "medium" | "hard",
  example?: string
];

function inferRuleCategory(cats: SpellCategoryId[]): SpellRuleCategory {
  if (cats.includes("i-before-e")) return "i-before-e";
  if (cats.includes("silent-letter")) return "silent-letter";
  if (cats.includes("double-consonant")) return "double-consonant";
  if (cats.includes("suffix-rules")) return "suffix-rules";
  return "common-traps";
}

function buildWords(raw: RawWordTuple[]): SpellWord[] {
  const seen = new Set<string>();
  const out: SpellWord[] = [];
  raw.forEach((item, idx) => {
    const [word, syllablesDot, meaningBn, categories, commonMistake, mnemonicBn, diff, ex] = item;
    const key = word.toLowerCase();
    if (seen.has(key)) return;
    seen.add(key);
    const syllables = syllablesDot.split("·");
    out.push({
      id: `sp-${String(idx + 1).padStart(3, "0")}`,
      word,
      syllables,
      phonetic: `/${syllables.join(".")}/`,
      meaningBn,
      categories,
      ruleCategory: inferRuleCategory(categories),
      commonMistake,
      mnemonicBn,
      mnemonicEn: `Break into chunks: ${syllables.join(" • ")} (avoid "${commonMistake}").`,
      exampleSentence: ex || `Please check the spelling of "${word}" carefully.`,
      difficulty: diff || (word.length >= 10 ? "hard" : word.length >= 7 ? "medium" : "easy"),
    });
  });
  return out;
}

